"""Review individually selected flags in surahs 18–33."""
import argparse
from semantic_review import ReviewBatch, validate


def main():
    parser=argparse.ArgumentParser(description=__doc__); parser.add_argument("--apply",action="store_true"); args=parser.parse_args()
    b=ReviewBatch("semantic-review-007","Individually reviewed constructions through surah 33, including relative pronouns, negative nearness, predicate support and quantified classes.")
    if b.exists: validate(); return
    def p(ay,ident,pieces,reason): b.phrase(ay+"-"+ident,[(t,f"{ay}:{w}" if w else None) for t,w in pieces],reason)
    def c(ay,ident,values,reason): b.change(ay+"-"+ident,{f"{ay}:{w}":t for w,t in values.items()},reason)
    def d(keys,reason,retained=False):
        for key in keys.split(): b.decide(key,reason,retained)
    d("18:86:18 18:86:21", "An introduces the two finite alternatives under imma/wa-imma. Turkish ya ... veya ... with edersin/davranırsın expresses those alternatives naturally without a separate infinitive ending; retain the contextual introducers rather than add a mismatched nominal clause.",True)
    c("18:87","topic-and-future",{2:"ise",5:"o halde yakında"},"Amma contrasts the wrongdoer's case, while fa-sawfa explicitly marks consequence and forthcoming punishment. Neither particle means a copied person or punishment predicate.")
