    p("22:28","livestock-class",[("besi ",15),("hayvanları",14),("ndan",13)],"Bahimati al-anam is the livestock-beast class, not all animals that walk. Turkish besi hayvanlarından exposes the beast/class/source roles with the class qualifier at al-anam.")
    c("22:28","eat-spelling",{16:"yiyin"},"Correct the standard Turkish imperative spelling encountered in the adjacent eat command.")
    d("22:28:15","Restore the livestock category rather than an unsupported walking-animal definition.")
    c("22:41","relative-people",{1:"[o] kimseler ki"},"Alladhina identifies those described by the following conditional; it does not mean the condition eğer itself.")
    d("22:41:1","Restore the relative persons while retaining if at in and the empowerment condition separately.")
    p("22:46","hearts-in-breasts",[("göğüsler",23),("de",22),("ki",21)],"Allati fi al-sudur qualifies the hearts in the breasts. Expose the Turkish relative -ki, locative -de and noun separately rather than duplicate içindeki.")
    d("22:46:21","Restore the nominal relative relation and keep the physical location at its source words.")
    p("22:71","other-than-Allah",[("Allah",4),("'tan",2),(" başka",3)],"Min duni Allahi is other than Allah; restore its actual components rather than place the following object şeylere at min.")
    p("22:71","no-revealed-authority",[("[Allah'ın] indir",7),("me",6),("diği [varlıklara]",5)],"Ma lam yunazzil qualifies the objects of worship for which no authority was revealed. Restore relative and negative scope instead of an independent finite indirmemiştir; mark the implicit divine subject and generic objects as explanatory support.")
    c("22:71","authority-reference",{8:"haklarında"},"Bihi refers back to the objects just named, naturally haklarında in the restored relative clause; the authority noun remains its object.")
    p("22:71","no-knowledge-relative",[("ve ",10),("kendilerinin ",12),("haklarında ",13),("bir bilgileri ",14),("olma",11),("yan [varlıklara]",10)],"Wa-ma laysa lahum bihi ilmun is the second relative object description: those about which they have no knowledge. Restore its nominal-relative ending and negative existence rather than a disconnected finite yoktur after a bare ve.")
    d("22:71:5","Restore the coordinated relative objects of worship and the absence of revealed authority/knowledge; explanatory nouns are bracketed, with Allah not reassigned as an idol possessor.")
    p("23:6","spousal-relation",[("eşleri",3),("yle",2)],"Ala azwajihim occurs within the sexual-guarding exception. Turkish eşleriyle expresses the spousal relation in that frame; -yle is contextual valency, not a universal instrumental definition of ala.")
    d("23:6:2","Expose the spousal relation without making the exception an unrestricted permission beyond its stated objects.")
    d("23:19:5 23:55:4 23:55:5","Individually retain the noun/class frames: palm/grape gardens and the wealth/sons provided. In the latter, bihi resumes the supplied-content relative and min identifies its wealth class; Turkish does not require a second overt resumptive object or a physical-source suffix.",True)
    p("23:50","dwelling-suitability",[("yerleşme",10),("ye elverişli",9)],"Dhat qararin describes a height possessing settlement suitability. Turkish yerleşmeye elverişli expresses that relationship; it does not claim dhat alone is a universal word for suitable.")
    d("23:50:9","Expose the relational contribution and retain the dwelling sense rather than only a context copy of the full adjective.")
    p("23:77","punishment-possessor",[("bir azab",7),("ın",6)],"Dha adh abin describes a gate associated with/possessing severe punishment. Turkish bir azabın kapısı expresses the relation through a genitive, not an omitted dh a.")
    c("23:77","gate-object",{5:"kapısını"},"The gate is the object of the opening in the restored Turkish possessed-noun construction; retain the required object inflection.")
    d("23:77:6","Restore the punishment-gate relation without changing the severity adjective that follows.")
    for ay in ["24:30","24:31"]:
        p(ay,"lowered-gaze",[("bakışları",5),("nı",4)],"Min absar marks the gaze under the lowering command. Turkish bakışlarını indirmek uses a direct object; expose that case in this functional valency rendering, not as a universal accusative definition of min or a command to close the eyes entirely.")
